open class Shape
class Circle : Shape()

open class Painter {
    open fun Shape.paint() = "Painter/Shape"
    open fun Circle.paint() = "Painter/Circle"
    fun draw(s: Shape) = s.paint()
}

class FancyPainter : Painter() {
    override fun Shape.paint() = "Fancy/Shape"
    override fun Circle.paint() = "Fancy/Circle"
}

fun main() {
    println(FancyPainter().draw(Circle()))
}
